from lessonlib import *
C11 = REF('ISO/IEC 9899:2011 (C11) draft N1570', 'https://www.open-std.org/jtc1/sc22/wg14/www/docs/n1570.pdf')
GFG = lambda label, url: REF('Reference: ' + label + ' (GeeksforGeeks)', url)
KR = REF('Kernighan & Ritchie, The C Programming Language, 2nd ed.', 'https://en.wikipedia.org/wiki/The_C_Programming_Language')
E, M, H = 'Easy', 'Medium', 'Hard'

write('arrays',
 "An array is a fixed-size block of same-typed elements stored contiguously in memory and accessed by zero-based index. Because the layout is contiguous, indexing is O(1), and arrays are the foundation under strings, matrices, buffers, and most data structures.",
 [S('Declaring and initializing', "The size is fixed at declaration (a constant expression, or a runtime value for a C99 variable-length array). Elements not covered by an initializer list are zero-filled; arrays with static storage duration are zero-initialized by default, while automatic arrays hold garbage.", code="int a[5];                    // uninitialized (automatic)\nint b[5] = {2, 4, 8};        // 2 4 8 0 0\nint c[] = {1, 2, 3};         // size deduced: 3\nint d[6] = {[2] = 7, [5] = 9};  // designated (C99): 0 0 7 0 0 9\nstatic int e[100];           // all zero"),
  S('Indexing and bounds', "Valid indices run from 0 to n-1. C never checks bounds: a[n] or a[-1] is undefined behavior and can silently corrupt neighbouring variables or crash. Looping with the wrong bound is the classic off-by-one bug.", code="for (int i = 0; i < 5; i++) b[i] *= 2;   // < 5, never <= 5"),
  S('Size of an array', "`sizeof` on a real array yields its total byte size, so the element count is `sizeof a / sizeof a[0]`. This only works where the array itself is in scope; once passed to a function it has decayed to a pointer and sizeof gives the pointer's size.", code="int n = sizeof b / sizeof b[0];   // 5"),
  S('Arrays and functions', "Arrays are passed by address: the name decays to a pointer to the first element, so the callee can modify the caller's elements but does not know the length. Always pass the length as a separate parameter.", code="void fill(int *a, size_t n, int v) { for (size_t i = 0; i < n; i++) a[i] = v; }\nfill(b, 5, 0);"),
  S('Multidimensional arrays', "A 2D array is an array of arrays laid out in row-major order: all of row 0, then row 1, and so on. When passing it, every dimension except the first must be given so the compiler can compute row strides.", code="int m[2][3] = {{1,2,3},{4,5,6}};   // memory: 1 2 3 4 5 6\nvoid show(int r[][3], int rows);    // column count required\n// m[i][j] == *(*(m + i) + j)")],
 [SUB('Array decay', 'When an array becomes a pointer.', S(None, "In most expressions an array name is converted to a pointer to its first element. Exceptions: operand of sizeof, operand of &, and a string literal initializing a char array. That is why `&a` has type `int (*)[5]` while `a` decays to `int *`.", code="int a[5];\nint *p = a;          // &a[0]\nint (*pa)[5] = &a;   // pointer to the whole array\nprintf(\"%zu %zu\\n\", sizeof a, sizeof p);  // 20 8")),
  SUB('Variable-length arrays', 'C99 VLAs and their risks.', S(None, "`int v[n];` allocates n elements on the stack at run time. It is convenient but a large or attacker-controlled n overflows the stack, and VLAs became optional in C11. Prefer malloc for sizes you do not control.")),
  SUB('Arrays versus pointers', 'They are not the same thing.', S(None, bullets=["An array owns storage; a pointer holds an address.", "sizeof differs: whole array versus pointer size.", "An array name is not assignable; a pointer is.", "They convert freely in expressions, which hides the difference."])),
  SUB('Common array algorithms', 'Patterns to know.', S(None, bullets=["Linear scan for sum, min, max.", "Two pointers from both ends (reverse, palindrome).", "In-place rotation by three reversals.", "Prefix sums for fast range queries.", "Sorting and binary searching."])),
  SUB('Advantages and limits', 'When to choose an array.', S(None, "Strengths: O(1) random access, cache-friendly contiguous layout, no per-element overhead. Limits: fixed size, O(n) insertion and deletion in the middle, no bounds checking. For growth, use a heap block you realloc (a dynamic array)."))],
 ["Contiguous, fixed-size, same-typed, zero-indexed.", "No bounds checking: out-of-range access is undefined behavior.", "Arrays decay to pointers when passed; pass the length separately.", "2D arrays are row-major; callee needs all but the first dimension."],
 [C11, KR, GFG('Arrays in C', 'https://www.geeksforgeeks.org/c/c-arrays/')],
 P(('Find the second largest element in one pass', E), ('Rotate an array right by k using three reversals', M), ('Merge two sorted arrays into a third', E), ('Transpose a matrix stored as int m[3][3]', E), ('Spiral-order traversal of a 2D array', M), ('Pass a 2D array to a function three different ways', M)))

write('strings',
 "A C string is a char array whose end is marked by the NUL character '\\0'. There is no string type and no length stored anywhere, so every library routine walks until it finds the terminator. Mismanaging that terminator or buffer size is behind a large share of C security bugs.",
 [S('Representation', "The string \"Geeks\" occupies 6 bytes: five characters plus the terminator. `strlen` counts characters before the NUL; `sizeof` of the array counts the NUL too.", code="char s[] = \"Geeks\";        // 6 bytes: G e e k s \\0\nchar t[6] = {'G','e','e','k','s','\\0'};\nprintf(\"%zu %zu\\n\", strlen(s), sizeof s);   // 5 6"),
  S('Array versus literal pointer', "`char s[] = \"hi\"` makes a modifiable copy on the stack. `const char *p = \"hi\"` points at a literal in read-only memory; writing through it is undefined behavior (usually a crash). Declare literal pointers `const` so the compiler catches mistakes.", code="char a[] = \"hi\"; a[0] = 'H';        // ok\nconst char *p = \"hi\"; /* p[0] = 'H'; */  // UB"),
  S('Reading strings safely', None, bullets=["`scanf(\"%s\")` stops at whitespace and has no bound: always give a width, `%19s`.", "`fgets(buf, sizeof buf, stdin)` reads a whole line including the newline and respects the buffer size.", "`gets` was removed in C11 because it cannot be used safely.", "Strip the trailing newline with `buf[strcspn(buf, \"\\n\")] = 0;`."], code="char line[64];\nif (fgets(line, sizeof line, stdin)) {\n  line[strcspn(line, \"\\n\")] = '\\0';\n}"),
  S('<string.h> essentials', None, bullets=["`strlen(s)`: length excluding NUL, O(n).", "`strcpy(d, s)`, `strcat(d, s)`: unbounded, caller must guarantee space.", "`strncpy(d, s, n)`: bounded, but may leave d without a NUL.", "`strcmp(a, b)`: <0, 0, >0; use it, never `==`, to compare contents.", "`strchr`, `strrchr`, `strstr`: find a character or substring.", "`memcpy`, `memmove`, `memset`: raw byte operations (use memmove when ranges overlap)."]),
  S('Typical pitfalls', None, bullets=["Forgetting room for the NUL when allocating: `malloc(strlen(s) + 1)`.", "Comparing with `==` compares addresses, not text.", "Modifying a string literal.", "Using a char array that is not terminated.", "Off-by-one in loops that copy characters."])],
 [SUB('Implementing strlen, strcpy, strcmp', 'Pointer idioms.', S(None, code="size_t my_strlen(const char *s) { const char *p = s; while (*p) p++; return p - s; }\nchar *my_strcpy(char *d, const char *s) { char *r = d; while ((*d++ = *s++)) ; return r; }\nint my_strcmp(const char *a, const char *b) {\n  while (*a && *a == *b) { a++; b++; }\n  return (unsigned char)*a - (unsigned char)*b;\n}")),
  SUB('Safer copying', 'snprintf and size-aware helpers.', S(None, "`snprintf(dst, sizeof dst, \"%s\", src)` always terminates and truncates safely; BSD `strlcpy` does the same. If you use `strncpy`, set the last byte to NUL yourself.", code="snprintf(dst, sizeof dst, \"%s\", src);")),
  SUB('Arrays of strings', 'char *argv[] and 2D char arrays.', S(None, "`char *names[] = {\"ann\", \"bob\"}` is an array of pointers to (possibly differently sized) literals. `char names[2][8]` is a block of fixed rows. `main(int argc, char *argv[])` receives the first form, terminated by a NULL pointer.")),
  SUB('Parsing and tokenizing', 'strtok and strtol.', S(None, "`strtok` splits in place by writing NULs into the string (and keeps hidden state, so it is not thread-safe; prefer `strtok_r`). `strtol(s, &end, 10)` converts numbers with error detection through `end` and `errno`, unlike `atoi`.")),
  SUB('Wide and UTF-8 text', 'Beyond ASCII.', S(None, "`char` strings in UTF-8 can hold multi-byte characters, so `strlen` counts bytes, not characters. `wchar_t` and `<wchar.h>` provide wide strings; for real Unicode handling use a library such as ICU."))],
 ["A string is a NUL-terminated char array; length is not stored.", "Size buffers for the NUL, and bound every read and copy.", "Literals are read-only: use const char * or a char array copy.", "Compare with strcmp, not ==."],
 [C11, KR, GFG('Strings in C', 'https://www.geeksforgeeks.org/c/strings-in-c/')],
 P(('Reverse a string in place', E), ('Check whether a string is a palindrome', E), ('Count vowels, consonants, and words in a line', E), ('Implement strstr naively', M), ('Remove duplicate characters from a string', M), ('Safely tokenize a CSV line with strtok_r', M)))

write('dynamic-memory',
 "Dynamic memory allocation lets a program request heap memory at run time, sized by data it only learns while running. C provides four functions in <stdlib.h>: malloc, calloc, realloc, and free. You must check every request and release every block exactly once.",
 [S('malloc', "`void *malloc(size_t size)` returns a pointer to `size` uninitialized bytes, or NULL on failure. The idiom `sizeof *p` keeps the size correct if the type changes.", code="int *p = malloc(10 * sizeof *p);\nif (p == NULL) { perror(\"malloc\"); return 1; }"),
  S('calloc', "`void *calloc(size_t n, size_t size)` allocates n elements and sets all bytes to zero. It also detects overflow in n * size, which a hand-written multiplication for malloc would not.", code="int *z = calloc(10, sizeof *z);   // all 0"),
  S('realloc', "`void *realloc(void *p, size_t new_size)` resizes a block, preserving contents up to the smaller size. It may move the block, so the old pointer becomes invalid. On failure it returns NULL and leaves the original block untouched, so never write `p = realloc(p, n)` directly (you would leak p).", code="int *tmp = realloc(p, 20 * sizeof *p);\nif (tmp == NULL) { /* p still valid: handle error */ }\nelse p = tmp;"),
  S('free', "`free(p)` returns a block obtained from malloc, calloc, or realloc. `free(NULL)` is a safe no-op. Freeing twice or freeing a pointer that did not come from the allocator is undefined behavior. Set the pointer to NULL afterward.", code="free(p);\np = NULL;"),
  S('A growable array', "Doubling capacity when full gives amortized O(1) appends.", code="typedef struct { int *data; size_t len, cap; } Vec;\nint push(Vec *v, int x) {\n  if (v->len == v->cap) {\n    size_t nc = v->cap ? v->cap * 2 : 4;\n    int *t = realloc(v->data, nc * sizeof *t);\n    if (!t) return -1;\n    v->data = t; v->cap = nc;\n  }\n  v->data[v->len++] = x; return 0;\n}")],
 [SUB('Allocating 2D arrays', 'Three layouts.', S(None, bullets=["One block of rows*cols ints, index as m[i*cols + j]: best locality and a single free.", "Array of row pointers, each malloc'd: flexible rows, many frees.", "Pointer to array: `int (*m)[cols] = malloc(rows * sizeof *m);` gives m[i][j] syntax with one block."])),
  SUB('Common errors', 'What goes wrong.', S(None, bullets=["Not checking for NULL.", "Memory leak: lost pointer, missing free.", "Use after free and double free.", "Buffer overrun: writing past the requested size.", "Wrong size such as `malloc(sizeof p)` for a pointer p (gives the pointer size).", "Casting malloc's result in C (unnecessary; can hide a missing #include <stdlib.h>)."])),
  SUB('How the allocator works', 'Why free needs no size.', S(None, "The allocator stores a small header before each block with its size, and keeps free blocks in bins or lists. glibc's ptmalloc uses arenas, and large requests use mmap. Metadata next to your data is why heap overflows are dangerous.")),
  SUB('Alignment and special allocators', 'aligned_alloc and alloca.', S(None, "malloc returns memory aligned for any standard type. `aligned_alloc(alignment, size)` (C11) or `posix_memalign` provide stricter alignment (SIMD, page-aligned I/O). `alloca` allocates on the stack and is non-standard and risky.")),
  SUB('Debugging heap bugs', 'Tools.', S(None, "Compile with `-fsanitize=address -g` to catch overflows, use-after-free, and leaks; run under Valgrind for similar reports; `mtrace` and `MALLOC_CHECK_` are lightweight glibc aids."))],
 ["malloc: uninitialized; calloc: zeroed and overflow-safe; realloc: may move; free: once only.", "Always check for NULL, and assign realloc to a temporary.", "Use sizeof *p, set pointers to NULL after free.", "Run sanitizers during testing."],
 [C11, GFG('Dynamic memory allocation in C', 'https://www.geeksforgeeks.org/c/dynamic-memory-allocation-in-c-using-malloc-calloc-free-and-realloc/'), REF('Linux man-pages: malloc(3)', 'https://man7.org/linux/man-pages/man3/malloc.3.html')],
 P(('Read n then allocate and sum n integers', E), ('Implement a growable vector with push and pop', M), ('Fix a realloc that leaks on failure', E), ('Allocate and free a rows x cols matrix in one block', M), ('Write strdup from scratch', E), ('Build a memory pool that hands out fixed-size blocks', H)))

write('structs-unions',
 "A struct groups values of different types under one name, with each member in its own storage. A union overlays its members in the same storage so only one is meaningful at a time. An enum names a set of integer constants. Together they let you model records, variants, and states.",
 [S('Structures', "Define a struct type, create variables, and access members with `.` (or `->` through a pointer). Initialize with a list or designated initializers; uninitialized automatic members hold garbage.", code="struct Student { char name[32]; int age; float gpa; };\nstruct Student s = {\"Vikas\", 20, 3.7f};\nstruct Student t = { .age = 18, .name = \"Anu\" };\nstruct Student *p = &s;\nprintf(\"%s %d\\n\", p->name, (*p).age);"),
  S('typedef, nesting, and self-reference', None, bullets=["`typedef struct {...} Student;` removes the need to write `struct` each time.", "Nested structs: `emp.addr.city`.", "A struct can hold a pointer to its own type, which is how linked lists and trees are built.", "Struct assignment copies all members (a shallow copy: pointers are copied, not what they point to)."], code="typedef struct Node { int val; struct Node *next; } Node;"),
  S('Passing and returning structs', "Structs are passed by value, copying every byte, so pass a `const struct *` for large ones. Returning small structs by value is fine and common."),
  S('Unions', "All members share one block whose size is the size of the largest member (plus any alignment padding). Writing one member overwrites the others. Reading a different member than was last written reinterprets the bytes (allowed for type punning in C, implementation-defined result).", code="union Value { int i; float f; unsigned char b[4]; };\nunion Value v; v.f = 1.0f;\nprintf(\"%08x\\n\", (unsigned)v.i);   // bit pattern of 1.0f: 3f800000"),
  S('Enumerations', "An enum defines named integer constants starting at 0 unless assigned. Use them in place of magic numbers, especially for states and error codes.", code="enum State { IDLE, RUNNING = 5, STOPPED };   // 0, 5, 6\nenum State st = RUNNING;")],
 [SUB('Tagged unions', 'A safe variant type.', S(None, "Pair a union with an enum tag that records which member is active, and switch on the tag before reading. This is how interpreters, protocol parsers, and many C APIs represent 'one of several types'.", code="struct Val { enum { INT, FLT } kind; union { int i; float f; } u; };\nvoid print(struct Val v) { if (v.kind == INT) printf(\"%d\", v.u.i); else printf(\"%f\", v.u.f); }")),
  SUB('Struct versus union', 'Quick comparison.', S(None, bullets=["Struct: size is at least the sum of members (plus padding); all members valid at once.", "Union: size is the largest member; only one valid at once.", "Both can be nested in each other.", "Anonymous unions (C11) expose members without a union name."])),
  SUB('Flexible array members', 'Variable-size structs (C99).', S(None, "A struct may end with an array of unspecified length, allocated together with its header, as used for packets and strings with a length prefix.", code="struct Buf { size_t len; char data[]; };\nstruct Buf *b = malloc(sizeof *b + 100);\nb->len = 100;")),
  SUB('Bit-fields', 'Packing flags in bits.', S(None, "`unsigned ready : 1;` allocates one bit. Layout and ordering are implementation-defined, so bit-fields are fine for compact in-memory flags but unreliable for wire formats or hardware registers across compilers.")),
  SUB('Deep versus shallow copy', 'Pointers inside structs.', S(None, "Copying a struct that contains a `char *name` duplicates only the pointer, so both copies refer to the same string and freeing one invalidates the other. Write a clone function that allocates and copies pointed-to data when you need independence."))],
 ["Struct members have separate storage; union members overlap.", "Use . for values and -> for pointers; pass big structs by const pointer.", "Combine a union with an enum tag to build safe variants.", "Struct copy is shallow; layout and padding follow alignment rules."],
 [C11, KR, GFG('Structures in C', 'https://www.geeksforgeeks.org/c/structures-c/'), GFG('Union in C', 'https://www.geeksforgeeks.org/c/union-c/')],
 P(('Define a Student struct and sort an array by GPA', E), ('Implement a tagged union calculator value', M), ('Print the bytes of a float using a union', E), ('Build a linked list of structs', M), ('Write a deep-copy function for a struct containing a string', M), ('Use a flexible array member for a length-prefixed message', H)))

write('bitwise',
 "Bitwise operators work directly on the individual bits of integers. They are the toolkit for flags, masks, packing data, hardware registers, and fast arithmetic tricks, and they underlie protocol headers and permissions.",
 [S('The six operators', None, code="a = 0b0111 (7), b = 0b0100 (4)\na & b  = 0b0100 (4)   AND: 1 only if both bits are 1\na | b  = 0b0111 (7)   OR : 1 if either is 1\na ^ b  = 0b0011 (3)   XOR: 1 if bits differ\n~b     = ...11111011  NOT: flips every bit  (~4 == -5 in two's complement)\na << 2 = 0b11100 (28) shift left : multiply by 2^n\na >> 1 = 0b0011 (3)  shift right: divide by 2^n (unsigned / non-negative)"),
  S('Shift rules', None, bullets=["Shifting by a negative amount or by >= the type's width is undefined behavior.", "Left-shifting a negative value, or shifting a 1 into the sign bit of a signed type, is undefined or problematic.", "Right shift of a negative signed value is implementation-defined (usually arithmetic, copying the sign bit).", "Prefer unsigned types for bit manipulation; use `1u << n` rather than `1 << n`."]),
  S('Core bit idioms', "With `n` the bit index (0 = least significant):", code="x |=  (1u << n);    // set bit n\nx &= ~(1u << n);    // clear bit n\nx ^=  (1u << n);    // toggle bit n\nint on = (x >> n) & 1u;   // test bit n"),
  S('Useful tricks', None, bullets=["Is power of two: `x && !(x & (x - 1))`.", "Clear lowest set bit: `x & (x - 1)` (loop gives popcount, Kernighan's method).", "Isolate lowest set bit: `x & -x`.", "Even/odd: `x & 1`.", "Swap without a temporary: `a ^= b; b ^= a; a ^= b;` (educational; fails if a and b alias).", "Single unique number among pairs: XOR everything."], code="int popcount(unsigned x) { int c = 0; while (x) { x &= x - 1; c++; } return c; }")],
 [SUB('Masks and flags', 'Packing booleans into one integer.', S(None, "Define one bit per option and combine with OR; test with AND. This is how file permissions, socket options, and many APIs work.", code="enum { F_READ = 1u << 0, F_WRITE = 1u << 1, F_EXEC = 1u << 2 };\nunsigned perm = F_READ | F_WRITE;\nif (perm & F_WRITE) puts(\"writable\");\nperm &= ~F_WRITE;   // drop write")),
  SUB('Extracting fields', 'Shift then mask.', S(None, "To read an N-bit field starting at bit s: `(x >> s) & ((1u << N) - 1)`. Example: the IPv4 IHL is the low nibble of the first byte, `b & 0x0F`, and the version is `b >> 4`.", code="uint8_t b = 0x45;\nunsigned version = b >> 4;      // 4\nunsigned ihl     = b & 0x0F;    // 5")),
  SUB('Why signed bit ops are risky', 'Integer promotion.', S(None, "Operands narrower than int are promoted to int, so `~uint8_t_value` becomes a negative int and comparisons surprise you. Cast the result back: `(uint8_t)~b`. Prefer fixed-width unsigned types such as uint32_t.")),
  SUB('Bit manipulation in hardware', 'Registers and volatile.', S(None, "Memory-mapped registers are read, masked, modified, and written back. Mark them `volatile` so the compiler does not remove or merge accesses, and use read-modify-write only when the register allows it.", code="#define REG (*(volatile uint32_t *)0x40021000)\nREG |= (1u << 5);")),
  SUB('Endianness and byte extraction', 'Portable byte access.', S(None, "Extract bytes with shifts, `(x >> 8) & 0xFF`, rather than casting pointers, so the result does not depend on host byte order."))],
 ["& masks, | sets, ^ toggles, ~ inverts, << and >> scale by powers of two.", "Use unsigned types and avoid out-of-range or signed shifts (UB).", "Set, clear, toggle, test: |= 1<<n, &= ~(1<<n), ^= 1<<n, (x>>n)&1.", "x & (x-1) clears the lowest set bit; this drives many tricks."],
 [C11, GFG('Bitwise operators in C', 'https://www.geeksforgeeks.org/c/bitwise-operators-in-c-cpp/'), REF('Bit Twiddling Hacks (Stanford)', 'https://graphics.stanford.edu/~seander/bithacks.html')],
 P(('Check whether a number is a power of two', E), ('Count set bits two ways', E), ('Find the single non-repeating element with XOR', E), ('Reverse the bits of a 32-bit integer', M), ('Swap odd and even bits', M), ('Pack and unpack an RGB565 color', M), ('Find the two missing numbers using XOR', H)))

write('storage-classes',
 "A variable's storage class decides where it lives, how long it exists (lifetime), where it is visible (scope), and across files whether the name can be shared (linkage). The four specifiers are auto, register, static, and extern.",
 [S('Scope, lifetime, and linkage', None, bullets=["Scope: where the name is visible (block, function, file).", "Storage duration: automatic (until the block ends), static (whole program run), or allocated (heap).", "Linkage: external (visible to other files), internal (this file only), or none (locals)."]),
  S('auto', "The default for variables declared inside a block. Created on entry, destroyed on exit, uninitialized (garbage) unless you assign. The keyword is almost never written.", code="void f(void) { auto int x = 5;  /* same as int x = 5; */ }"),
  S('register', "A hint that a variable is heavily used and should be kept in a CPU register. Modern compilers ignore it, and you cannot take the address of a register variable.", code="register int i;   // &i is an error"),
  S('static', "Two meanings depending on where it appears:", bullets=["Inside a function: the variable lives for the whole program but is visible only in that function, keeps its value between calls, and is initialized once to zero by default.", "At file scope (global function or variable): internal linkage, so the name is private to the translation unit."], code="int next_id(void) {\n  static int id = 0;   // initialized once\n  return ++id;         // 1, 2, 3, ...\n}"),
  S('extern', "Declares that a variable or function is defined in another translation unit; it allocates no storage. The linker resolves the reference. Put extern declarations in a header and the single definition in one .c file.", code="/* config.h */ extern int verbose;\n/* config.c */ int verbose = 0;\n/* main.c   */ #include \"config.h\"   // uses verbose")],
 [SUB('Where each lives in memory', 'Tie-back to the layout.', S(None, bullets=["auto/register: stack (or a register).", "static and extern with initializers: initialized data segment.", "static and extern without initializers: BSS, zero-filled.", "malloc'd memory: heap."])),
  SUB('Default initial values', 'A quick table.', S(None, bullets=["auto, register: indeterminate (garbage).", "static, extern (and any global): zero.", "malloc: indeterminate; calloc: zero."])),
  SUB('Static for encapsulation', 'Hiding helpers.', S(None, "Marking helper functions and file globals `static` prevents name collisions across files and lets the compiler inline or drop unused ones. It is the C equivalent of 'private'.")),
  SUB('Thread storage and const', '_Thread_local and const.', S(None, "`_Thread_local` (C11) gives each thread its own copy. A `const` global has internal linkage in C++ but external linkage in C, a classic porting difference.")),
  SUB('Pitfalls', 'Common mistakes.', S(None, bullets=["Returning the address of an auto variable.", "Using static locals in code that must be re-entrant or thread-safe (the hidden shared state breaks it).", "Defining a global in a header, creating duplicate definitions at link time.", "Assuming auto variables are zero."]))],
 ["auto is the default for locals; static locals persist between calls.", "static at file scope means internal linkage; extern shares a name across files.", "Static-duration variables are zero-initialized; automatic ones are not.", "register is only a hint, and its address cannot be taken."],
 [C11, KR, GFG('Storage classes in C', 'https://www.geeksforgeeks.org/c/storage-classes-in-c/')],
 P(('Write a function that counts how many times it has been called', E), ('Predict the output of a program with static and auto counters', E), ('Share a variable between two .c files with extern', M), ('Make a helper function private to its file', E), ('Explain why a header must not define a global variable', M)))

write('preprocessor',
 "The C preprocessor is a text-substitution step that runs before compilation. It includes files, defines macros, and conditionally keeps or drops code. Because it works on tokens, not types or scopes, macros are powerful and easy to misuse.",
 [S('#include', "`#include <file>` searches system directories; `#include \"file\"` searches the current directory first. The preprocessor pastes the file's contents in place.", code="#include <stdio.h>\n#include \"mylib.h\""),
  S('Object-like macros', "A name replaced by tokens, commonly for constants. Prefer `enum` or `const` for typed constants; use #define when you need a preprocessor-time value.", code="#define BUFSIZE 1024\n#define PI 3.14159"),
  S('Function-like macros', "Macros with parameters expand textually, so they must be parenthesized carefully; arguments with side effects can be evaluated more than once.", code="#define SQR_BAD(x) x * x\n#define SQR(x)     ((x) * (x))\nSQR_BAD(1 + 2)   // 1 + 2 * 1 + 2 = 5, not 9\nSQR(i++)         // i incremented twice: undefined behavior"),
  S('Conditional compilation', None, bullets=["`#ifdef NAME` / `#ifndef NAME` / `#if expr` / `#elif` / `#else` / `#endif` select code at build time.", "Use for platform differences, debug builds, and feature flags.", "`#if 0 ... #endif` temporarily disables a block."], code="#ifdef DEBUG\n  #define LOG(msg) fprintf(stderr, \"%s:%d %s\\n\", __FILE__, __LINE__, msg)\n#else\n  #define LOG(msg) ((void)0)\n#endif"),
  S('Include guards', "A header can be included twice through different paths, causing redefinition errors. Guard it so the body is seen once, or use the widely supported `#pragma once`.", code="#ifndef MYLIB_H\n#define MYLIB_H\n/* declarations */\n#endif")],
 [SUB('Stringification and token pasting', '# and ##.', S(None, "`#x` turns a macro argument into a string literal; `a ## b` glues two tokens into one identifier.", code="#define STR(x) #x\n#define CAT(a, b) a##b\nprintf(\"%s\\n\", STR(hello));   // hello\nint CAT(var, 1) = 5;            // int var1 = 5;")),
  SUB('Predefined macros', 'Built-in context.', S(None, bullets=["`__FILE__`, `__LINE__`: current file and line.", "`__func__`: current function name (C99, not a macro).", "`__DATE__`, `__TIME__`: compile time.", "`__STDC_VERSION__`: the C standard in use (e.g. 201112L).", "`NDEBUG`: when defined, `assert` is disabled."])),
  SUB('Safe multi-statement macros', 'do { } while (0).', S(None, "Wrap multi-statement macros so they behave as one statement and work after `if` without braces.", code="#define SWAP(a, b) do { __typeof__(a) t = (a); (a) = (b); (b) = t; } while (0)")),
  SUB('Macros versus inline functions', 'Prefer functions when you can.', S(None, "`static inline` functions are type-checked, evaluate arguments once, show up in debuggers, and are usually as fast. Use macros for things functions cannot do: conditional compilation, token pasting, `__FILE__`/`__LINE__` capture, and generic helpers.")),
  SUB('Inspecting expansion', 'See what the preprocessor did.', S(None, "`gcc -E file.c` prints the preprocessed output; `-D NAME=value` defines a macro from the command line; `-I dir` adds an include path.", code="gcc -E -DDEBUG main.c | less"))],
 ["The preprocessor does text substitution before compilation.", "Parenthesize macro parameters and the whole expansion; avoid arguments with side effects.", "Use include guards or #pragma once in every header.", "Prefer enum, const, and inline functions to macros where possible."],
 [C11, REF('GNU C Preprocessor manual', 'https://gcc.gnu.org/onlinedocs/cpp/'), KR],
 P(('Write MAX and MIN macros that avoid double evaluation', M), ('Add include guards to a header and test double inclusion', E), ('Implement a debug-only logging macro with file and line', E), ('Create an X-macro that defines an enum and its string table', H), ('Show why #define SQR(x) x*x is wrong', E)))

write('file-io',
 "C reads and writes files through the stdio library using a FILE * stream. You open a file with a mode, read or write with formatted, character, line, or binary functions, move the position indicator if needed, and close the stream.",
 [S('Opening and closing', "`fopen(path, mode)` returns a FILE * or NULL on failure; always test it and report errors with `perror`. Close with `fclose` to flush buffers and release the descriptor.", code="FILE *f = fopen(\"data.txt\", \"r\");\nif (!f) { perror(\"fopen\"); return 1; }\n/* ... */\nfclose(f);"),
  S('Modes', None, bullets=["\"r\": read, file must exist.", "\"w\": write, create or truncate.", "\"a\": append, create if missing.", "\"r+\", \"w+\", \"a+\": read and write variants.", "Add \"b\" for binary (\"rb\", \"wb\"); it only matters on systems that translate newlines, like Windows."]),
  S('Reading and writing text', None, bullets=["`fgetc` / `fputc`: one character.", "`fgets(buf, n, f)` / `fputs`: a line.", "`fscanf` / `fprintf`: formatted values.", "Loop on the return value, not on `feof`: `while (fgets(line, sizeof line, f)) { ... }`."], code="char line[256];\nwhile (fgets(line, sizeof line, f)) {\n  fputs(line, stdout);\n}"),
  S('Binary I/O', "`fread(ptr, size, count, f)` and `fwrite(ptr, size, count, f)` move raw bytes and return the number of items transferred. Writing whole structs is quick but not portable across padding, endianness, or compilers.", code="struct Rec { int id; double val; } r = {1, 2.5};\nFILE *b = fopen(\"rec.bin\", \"wb\");\nfwrite(&r, sizeof r, 1, b);\nfclose(b);"),
  S('Positioning', None, bullets=["`ftell(f)`: current offset.", "`fseek(f, offset, SEEK_SET | SEEK_CUR | SEEK_END)`: move.", "`rewind(f)`: back to the start and clear error flags."], code="fseek(f, 0, SEEK_END);\nlong size = ftell(f);\nrewind(f);")],
 [SUB('Error handling', 'ferror, feof, errno.', S(None, "Functions return EOF or a short count on trouble. Distinguish end-of-file from error with `feof(f)` and `ferror(f)`, and inspect `errno` / `perror` for the reason. Check `fclose` and `fflush` results when writing important data, since buffered writes can fail late.")),
  SUB('Buffering', 'Why output sometimes appears late.', S(None, "stdio buffers output: line-buffered for terminals, fully buffered for files. `fflush(f)` forces a flush; `setvbuf` changes the mode. A crash before flush loses buffered data.")),
  SUB('Standard streams and redirection', 'stdin, stdout, stderr.', S(None, "Three streams are open at start. Errors belong on stderr (unbuffered) so they are visible even when stdout is redirected. `freopen` rebinds a stream to a file.")),
  SUB('Reading a whole file', 'A common helper.', S(None, code="char *slurp(const char *path, size_t *n) {\n  FILE *f = fopen(path, \"rb\"); if (!f) return NULL;\n  fseek(f, 0, SEEK_END); long sz = ftell(f); rewind(f);\n  char *buf = malloc(sz + 1);\n  if (buf && fread(buf, 1, sz, f) == (size_t)sz) { buf[sz] = 0; if (n) *n = sz; }\n  else { free(buf); buf = NULL; }\n  fclose(f); return buf;\n}")),
  SUB('POSIX file descriptors', 'Lower-level alternative.', S(None, "`open`, `read`, `write`, `close` operate on integer descriptors with no stdio buffering and are used for sockets, pipes, and devices. `fileno(f)` and `fdopen(fd, mode)` convert between the two."))],
 ["Open with fopen, always test for NULL, close with fclose.", "Choose text functions (fgets, fprintf) or binary (fread, fwrite) deliberately.", "Loop on read return values, not on feof.", "Output is buffered; flush or close to persist it."],
 [C11, GFG('File handling in C', 'https://www.geeksforgeeks.org/c/basics-file-handling-c/'), REF('Linux man-pages: fopen(3)', 'https://man7.org/linux/man-pages/man3/fopen.3.html')],
 P(('Copy one file to another in blocks', E), ('Count lines, words, and characters in a file', E), ('Read records from a CSV into an array of structs', M), ('Store and retrieve structs with fwrite/fread and fseek', M), ('Implement tail -n by seeking from the end', H)))

write('qualifiers',
 "Type qualifiers add promises about how an object may be used. const says the program will not modify it, volatile says its value can change outside the program's control, and restrict says a pointer is the only way to reach the object. They help both the compiler and other programmers.",
 [S('const', "A const object cannot be modified through its name; trying to is a compile error. For objects defined const, modifying them through a cast pointer is undefined behavior. const improves safety, documents intent, and lets the compiler place data in read-only memory.", code="const int max = 100;\n// max = 200;          // error\nconst double pi = 3.14159;"),
  S('const and pointers', "Read declarations right to left. Three forms:", bullets=["`const int *p` (pointer to const int): cannot modify *p; can re-point p.", "`int *const p` (const pointer): can modify *p; cannot re-point p.", "`const int *const p`: neither."], code="int x = 1, y = 2;\nconst int *a = &x;  a = &y;   /* *a = 5; error */\nint *const b = &x;  *b = 5;    /* b = &y; error */"),
  S('const correctness in APIs', "Mark parameters you do not modify as pointer-to-const. It documents the contract, lets callers pass const data, and prevents accidents. The standard library does this: `size_t strlen(const char *s)`.", code="size_t count(const int *a, size_t n);   // promises not to write"),
  S('volatile', "Tells the compiler the object may change unexpectedly or that accesses have side effects, so every read and write in the source must really happen, in order. Without it the compiler may cache the value in a register or delete a loop that polls it.", bullets=["Memory-mapped hardware registers.", "Variables changed by a signal handler (use `volatile sig_atomic_t`).", "Objects shared with setjmp/longjmp code."], code="volatile int ready = 0;\nwhile (!ready) { /* wait: re-read each time */ }"),
  S('restrict (C99)', "A promise that, for the lifetime of the pointer, the object it points to is accessed only through that pointer (or pointers derived from it). It lets the compiler optimize aggressively, as in `memcpy`, whose arguments must not overlap. Breaking the promise is undefined behavior.", code="void *memcpy(void *restrict dst, const void *restrict src, size_t n);")],
 [SUB('const is not thread safety or immutability', 'Common misconceptions.', S(None, "A `const` view of data does not stop another pointer from modifying it, so it is not a synchronization tool. volatile is likewise not an atomic type: use `_Atomic` or mutexes for threads.")),
  SUB('Casting away const', 'Why not to.', S(None, "Casting const away and writing to a genuinely const object is undefined behavior. It is acceptable only when you know the underlying object was not defined const, such as the return type of `strchr(const char *, int)` returning `char *`.")),
  SUB('Combining qualifiers', 'const volatile.', S(None, "A read-only hardware status register is `const volatile uint32_t *`: your code must not write it, yet its value changes by itself.", code="const volatile uint32_t *status = (const volatile uint32_t *)0x40000000;")),
  SUB('Where const data lives', 'Storage.', S(None, "String literals and file-scope const data usually go in a read-only section (.rodata), shared between processes and protected by the MMU. Local const variables still live on the stack and can be changed by buggy code.")),
  SUB('Compiler warnings to enable', 'Catch qualifier misuse.', S(None, "`-Wall -Wextra -Wcast-qual -Wdiscarded-qualifiers` flag casts and assignments that drop const, protecting API contracts."))],
 ["const forbids modification; read pointer declarations right to left.", "Use pointer-to-const for read-only parameters.", "volatile forces real memory accesses for hardware, signals, and setjmp.", "restrict promises no aliasing and enables optimization; violating it is UB."],
 [C11, GFG('const qualifier in C', 'https://www.geeksforgeeks.org/c/const-qualifier-in-c/'), REF('cppreference: Type qualifiers (C)', 'https://en.cppreference.com/w/c/language/declarations')],
 P(('Explain the difference between three pointer-const declarations', E), ('Add const correctness to a small string library', M), ('Explain why a polling loop needs volatile', M), ('Declare a read-only memory-mapped status register', M), ('Why must memcpy arguments use restrict and not overlap?', H)))
print('ok')
